preConditionHook:
// TrueRangeCoefficientOfVariation (Brian's notes ON-57-b, #57): the
// population StdDev of the true range over the last lookback bars is at most
// cvMax x their mean -- steady volatility. Negate for erratic volatility.
// Product form, no divide (EL raises on a zero divisor). CV is taken on true
// range, not close: CV of a price fails the shift test.
// Plain EL Average(TrueRange, n) and StdDev(TrueRange, n): FRESH every bar
// over the price expression (TrueRangeAvgRatio is the precedent), summed
// NEWEST-FIRST, population form; StdDev's own Average is the same mean.
// TrueRange is the two-term max(H, C[1]) - min(L, C[1]).
trMean = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
    double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
    trMean += hi - lo;
}
trMean /= (int)lookback;
trSd = 0.0;
for (int i = 0; i < (int)lookback; ++i) {
    double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
    double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
    double dev = (hi - lo) - trMean;
    trSd += dev * dev;
}
trSd = std::sqrt(trSd / (int)lookback);
